// WF18 - Busca na Base de Conhecimento (KnowbaseItem) do GLPI via API v1
const helpers = this.helpers;
const baseV1 = 'https://suporte.araraquara.sp.gov.br/api.php/v1';
const appToken = $('Carregar Tokens').first().json.app_token;
const userToken = $('Carregar Tokens').first().json.user_token;

const inJson = $input.first().json || {};
const termo = String(inJson.termo || inJson.query || '').trim();
const limit = Number(inJson.limit) > 0 ? Number(inJson.limit) : 5;

async function callRaw(method, url, headers) {
  const resp = await helpers.httpRequest({ method, url, headers, json: false, returnFullResponse: true, ignoreHttpStatusErrors: true, skipSslCertificateValidation: true });
  let parsed = resp.body;
  if (typeof parsed === 'string') { try { parsed = JSON.parse(parsed); } catch (_) {} }
  return { status: resp.statusCode || resp.status, body: parsed };
}

if (!termo) {
  return [{ json: { resposta: 'Por favor, descreva em poucas palavras o que voce quer pesquisar na base de conhecimento.' } }];
}

const r0 = await callRaw('GET', `${baseV1}/initSession`, { 'App-Token': appToken, 'Authorization': `user_token ${userToken}` });
if (r0.status !== 200 || !r0.body || !r0.body.session_token) {
  return [{ json: { resposta: 'Nao consegui consultar a base de conhecimento agora. Tente novamente em instantes ou abra um chamado.' } }];
}
const H = { 'App-Token': appToken, 'Session-Token': r0.body.session_token };

async function buscar(field) {
  const url = `${baseV1}/KnowbaseItem?searchText[${field}]=${encodeURIComponent(termo)}&range=0-${limit * 2}`;
  const r = await callRaw('GET', url, H);
  return Array.isArray(r.body) ? r.body : (r.body && r.body.data ? r.body.data : []);
}

let itens = [];
try { itens = itens.concat(await buscar('name')); } catch (_) {}
try { itens = itens.concat(await buscar('answer')); } catch (_) {}
try { await callRaw('GET', `${baseV1}/killSession`, H); } catch (_) {}

const vistos = {};
const unicos = [];
for (const it of itens) {
  if (it && it.id && !vistos[it.id]) { vistos[it.id] = 1; unicos.push(it); }
}

if (!unicos.length) {
  return [{ json: { resposta: `Nao encontrei artigos na base de conhecimento sobre "${termo}". Se preferir, posso abrir um chamado para voce ser atendido.` } }];
}

const top = unicos.slice(0, limit).map((it, i) => {
  const titulo = String(it.name || 'Artigo');
  let corpo = String(it.answer || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
  if (corpo.length > 500) corpo = corpo.substring(0, 500) + '...';
  return `${i + 1}. *${titulo}*\n${corpo}`;
}).join('\n\n');

return [{ json: { resposta: `Encontrei na base de conhecimento do GLPI:\n\n${top}\n\nSe nao resolver, posso abrir um chamado para voce.` } }];
